function tokenize(text) {
  var normalized = normalize(text);
  var tokens = [];
  var current = '';
  for (var i = 0; i < normalized.length; i++) {
    var ch = normalized[i];
    if (isAsciiAlnum(ch)) {
      current += ch;
    } else {
      if (current.length > 0) {
        tokens.push(current);
        current = '';
      }
    }
  }
  if (current.length > 0) {
    tokens.push(current);
  }
  return tokens;
}

function normalize(text) {
  var normalized = text.normalize('NFKC');
  var result = '';
  var inWhitespace = false;
  for (var i = 0; i < normalized.length; i++) {
    var ch = normalized[i];
    if (isWhitespace(ch)) {
      if (!inWhitespace) {
        if (result.length > 0) {
          result += ' ';
        }
        inWhitespace = true;
      }
    } else {
      result += ch;
      inWhitespace = false;
    }
  }
  return result;
}

function isWhitespace(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\v' || ch === '\f' ||
    ch === '\u00a0' || ch === '\u1680' || ch === '\u2000' || ch === '\u2001' || ch === '\u2002' ||
    ch === '\u2003' || ch === '\u2004' || ch === '\u2005' || ch === '\u2006' || ch === '\u2007' ||
    ch === '\u2008' || ch === '\u2009' || ch === '\u200a' || ch === '\u2028' || ch === '\u2029' ||
    ch === '\u202f' || ch === '\u205f' || ch === '\u3000';
}

function isAsciiAlnum(ch) {
  var code = ch.charCodeAt(0);
  return (code >= 48 && code <= 57) || (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
}

